def refs_html(ids):
 return ' · '.join(f'<a href="{e(SOURCES[i][1])}">{i} {e(SOURCES[i][0])}</a>' for i in ids)
def slide_html(s):
 n=s['number']; title=s['title'];
 return f'''<section class="slide" id="slide-{n:02d}" data-number="{n}" data-seconds="{s['seconds']}" aria-label="{e(title)}">
 <header><div class="eyebrow">{n:02d} / {e(s['section'])}</div><h1>{title}</h1><img class="logo" src="assets/lig-logo.png" alt="LIG D&A"></header>
 <main>{('<p class="condition">'+e(s['condition'])+'</p>') if s['condition'] else ''}{s['body']}</main>
 <div class="slide-source">{refs_html(s['refs'])}</div>
 <footer><span>5팀 올빼미 · LWIR 표적 추적</span><span>{'확정 전 초안 · ' if s['pending'] else ''}{n:02d} / 18</span></footer>
 </section>'''

